// Blast radius: when a Bash command is about to ask for permission, preview what it would
// do. The built-in check measures any `rm`; user rules run a dry-run command per matching
// command in a chain or pipe. One line goes under the dialog, the details to a side pane.
// Display only, never in the model's context, and the verdict passes through untouched:
// the parser's blind spots must stay cosmetic misses, never holes in a gate.

import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register } from 'claude-code'

import type { PreviewRun, Report } from '../types'
import { format, size } from './format'
import { parse, segments } from './parse'
import { absolute, probe, type Host } from './probe'
import { optionsOf, plan, rulesOf, SOURCES } from './rules'

const PANE = 'blast-radius'
// `/blast-radius off` stores false: the pane then opens only when asked for
const AUTO_OPEN = 'autoOpen'
const report = atom({ plugin: 'blast-radius', key: 'report' } as const, null)

const PREVIEW_MS = 10_000
const MAX_LINES = 200

function hostOf($: EngineInterface, cwd: string, home: string | undefined): Host {
  return {
    cwd,
    home,
    run: (argv, init) => $.process.run(argv, init),
    stat: path => $.fs.stat(path).catch(() => undefined),
    list: dir => $.fs.list(dir),
  }
}

function notice($: EngineInterface, id: string, text: string) {
  try {
    $.ui.notice(id, text)
  } catch {
    // dialog already answered: nothing left to tell
  }
}

async function loadRules($: EngineInterface) {
  const sources = await Promise.all(SOURCES.map(source => $.settings.read({ source }).catch(() => undefined)))
  return rulesOf(optionsOf(sources))
}

async function autoOpen($: EngineInterface) {
  return (await $.store.get(AUTO_OPEN).catch(() => undefined)) !== false
}

// the pane opened unasked for a prompt: closed once that prompt is answered.
// Module state: a reload starts over, at worst leaving one pane open.
const pane = { opened: undefined as string | undefined, answered: new Set<string>() }

async function closeFor($: EngineInterface, id: string) {
  pane.answered.add(id)
  if (pane.opened !== id) return
  pane.opened = undefined
  await $.ui.close({ id: PANE }).catch(() => {})
}

// opens the pane for prompt `id`, claimed for closing only when it was not open already
// (opened with `/blast-radius`, or still up for another prompt)
async function openFor($: EngineInterface, id: string) {
  const wasOpen = (await $.ui.panes().catch(() => [])).some(p => p.id === PANE)
  const placed = await $.ui.open({ id: PANE, title: 'Blast radius' }).then(
    r => r.isPlaced,
    () => false,
  )
  if (!wasOpen) {
    pane.opened = id
    // answered while the pane was opening: close it straight away
    if (pane.answered.has(id)) await closeFor($, id)
  }
  return placed
}

async function analyze($: EngineInterface, id: string, command: string) {
  const removal = parse(command)
  const { rules, errors } = await loadRules($)
  const plans = segments(command).flatMap(s => rules.flatMap(r => plan(r, s) ?? []))
  if (!removal && !plans.length) return

  const set = (fn: (r: Report) => Report) => update($, report, cur => (cur?.id === id ? fn(cur) : cur))
  const previews: PreviewRun[] = plans.map(p =>
    'skip' in p ? { ...p, state: 'done', lines: [], more: 0 } : { ...p, state: 'running', lines: [], more: 0 },
  )
  const fresh: Report = {
    id,
    command,
    rm: removal && { state: 'running', line: 'measuring…', items: [] },
    previews,
    errors,
  }
  await update($, report, () => fresh)
  // opened unasked: a narrow terminal (under 144 columns) keeps it undrawn, so the line says how to see it
  const placed = (await autoOpen($)) && (await openFor($, id))
  const withHint = (...parts: (string | false | null | undefined)[]) =>
    [...parts, !placed && 'details: /blast-radius'].filter(Boolean).join(' · ')
  const dryRuns = previews.length
    ? `🔍 ${previews.length} dry-run${previews.length === 1 ? '' : 's'}${placed ? ' in the Blast radius pane' : ''}`
    : ''
  notice($, id, withHint(removal && '💥 rm: measuring…', dryRuns))

  const [cwd, home] = await Promise.all([$.session.cwd(), $.env.get('HOME')])
  const host = hostOf($, cwd, home)

  const rmDone = removal
    ? probe(host, removal).then(async impact => {
        const line = format(impact)
        await set(r => ({ ...r, rm: { state: 'done', line, items: impact.items } }))
        return line
      })
    : Promise.resolve('')

  await Promise.all(
    previews.map(async (p, i) => {
      if (!p.argv) return
      const dir = absolute(host, '', p.dir || '.') ?? cwd
      const done = await host
        .run(p.argv, { cwd: dir, timeoutMs: PREVIEW_MS })
        .then(r => {
          const all = `${r.stdout}\n${r.exitCode === 0 ? '' : (r.stderr ?? '')}`.split('\n').filter(l => l.trim())
          return { exitCode: r.exitCode, lines: all.slice(0, MAX_LINES), more: Math.max(0, all.length - MAX_LINES) }
        })
        .catch((err: unknown) => ({ exitCode: -1, lines: [String(err)], more: 0 }))
      await set(r => ({ ...r, previews: r.previews.map((q, j) => (j === i ? { ...q, state: 'done', ...done } : q)) }))
    }),
  )
  notice($, id, withHint(await rmDone, dryRuns))
}

export const register: Register = on => {
  const seen = new Set<string>()

  on('session.start', async ($, e, next) => {
    await $.command.register({
      name: 'blast-radius',
      description: 'Show the Blast radius pane (last previewed command); `off` / `on`: stop / resume opening it by itself',
    })
    return next(e)
  })

  on('command.run', { command: 'blast-radius' }, async ($, e) => {
    const arg = e.args.trim().toLowerCase()
    // asked for: stays open after the prompt it was opened for
    pane.opened = undefined
    if (arg === 'off') {
      await $.store.set(AUTO_OPEN, false)
      await $.ui.close({ id: PANE }).catch(() => {})
      return { text: 'Blast radius pane closed; it no longer opens by itself. `/blast-radius on` to undo.' }
    }
    if (arg === 'on') await $.store.set(AUTO_OPEN, true)
    else if (arg) return { text: `Unknown argument "${arg}": /blast-radius [on|off]` }
    await $.ui.open({ id: PANE, title: 'Blast radius' })
    return { text: arg === 'on' ? 'Blast radius pane opened; it opens by itself again.' : 'Blast radius pane opened.' }
  })

  // next(e) runs the permission prompt and the tool: once it settles, the prompt is answered
  on('tool.call', { tool: 'Bash' }, async ($, e, next) => {
    try {
      return await next(e)
    } finally {
      await closeFor($, e.tool_use_id)
    }
  })

  on('tool.check', { tool: 'Bash' }, async ($, e, next) => {
    const verdict = await next(e)
    const id = e.tool_use_id
    const command = (e.input as { command?: unknown }).command
    if (verdict.decision !== 'ask' || !id || seen.has(id) || typeof command !== 'string') return verdict
    seen.add(id)
    // not awaited: the dialog opens now, the line and pane fill in as the probes finish
    analyze($, id, command).catch(err => notice($, id, `💥 could not preview (${String(err).slice(0, 60)})`))
    return verdict
  })

  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e) => {
    const { Box, Text } = $.ui.resolve(e)
    const r = await read($, report)
    if (!r) return <Text dimColor>Nothing yet: opens when a permission prompt has an rm or matches a rule.</Text>

    const rows: ReturnType<typeof Text>[] = []
    rows.push(<Text dimColor>$ {r.command}</Text>)
    for (const err of r.errors) rows.push(<Text color="yellow">⚠ config: {err}</Text>)
    if (r.rm) {
      rows.push(<Text bold>{r.rm.line}</Text>)
      for (const it of r.rm.items)
        rows.push(
          <Text>
            {'  '}
            {it.path}
            {it.kind === 'dir' ? '/' : ''}
            <Text dimColor>
              {'  '}
              {it.files} file{it.files === 1 ? '' : 's'} · {size(it.bytes)}
            </Text>
          </Text>,
        )
    }
    for (const p of r.previews) {
      rows.push(
        <Text bold>
          🔍 {p.rule}: {p.argv ? p.argv.join(' ') : p.segment}
        </Text>,
      )
      if (p.skip) rows.push(<Text color="yellow">{'  '}skipped: {p.skip}</Text>)
      else if (p.state === 'running') rows.push(<Text dimColor>{'  '}running…</Text>)
      else {
        if (p.exitCode !== 0) rows.push(<Text color="red">{'  '}exit {p.exitCode}</Text>)
        if (!p.lines.length) rows.push(<Text dimColor>{'  '}(no output)</Text>)
        for (const l of p.lines) rows.push(<Text>{'  '}{l}</Text>)
        if (p.more) rows.push(<Text dimColor>{'  '}… {p.more} more lines</Text>)
      }
    }

    const room = Math.max(3, (e.viewport?.rows ?? 30) - 2)
    const shown = rows.length > room ? [...rows.slice(0, room - 1), <Text dimColor>… {rows.length - room + 1} more rows</Text>] : rows
    return <Box flexDirection="column">{shown}</Box>
  })
}

files.hooks/format.ts:
// One line under the permission dialog: worst news first, so a glance is enough.

import type { Flag, Impact } from './probe'

const DANGER: [Flag, string][] = [
  ['root', '⛔ deletes /'],
  ['home', '⛔ deletes $HOME'],
  ['cwd', '⛔ deletes the project'],
  ['git-dir', '⛔ deletes .git history'],
]

const count = (n: number) => n.toLocaleString('en-US')

export function size(bytes: number): string {
  const units = ['B', 'KB', 'MB', 'GB', 'TB']
  let v = bytes
  let u = 0
  while (v >= 1024 && u < units.length - 1) {
    v /= 1024
    u++
  }
  return `${v >= 10 ? Math.round(v) : Number(v.toFixed(1))} ${units[u]}`
}

export function format(i: Impact): string {
  const parts: string[] = []
  for (const [flag, text] of DANGER) if (i.flags.includes(flag)) parts.push(text)

  if (i.files > 0 || i.filesCapped) {
    // gitignored files are lost too (.env, local config): git can't bring them back either
    const lost = i.unsaved + i.ignored
    if (i.gitUnknown) parts.push('git status unknown')
    else if (lost > 0) parts.push(`⚠ ${count(lost)} not in git${i.ignored > 0 ? ` (${count(i.ignored)} gitignored)` : ''}`)
    else parts.push('all in git')
    parts.push(`${i.filesCapped ? '≥' : ''}${count(i.files)} file${i.files === 1 ? '' : 's'}`)
    parts.push(i.sizeUnknown ? `≥${size(i.bytes)}` : size(i.bytes))
  }
  if (i.flags.includes('outside-cwd') && !DANGER.some(([f]) => i.flags.includes(f))) parts.push('outside project')
  if (i.dirsWithoutR > 0) parts.push(`${i.dirsWithoutR} dir${i.dirsWithoutR === 1 ? '' : 's'} skipped (no -r)`)
  if (i.missing > 0) parts.push(`${i.missing} not found`)
  if (i.unresolved > 0) parts.push(`${i.unresolved} unresolved ($VAR/xargs)`)
  if (!parts.length) parts.push('nothing to delete')

  return `💥 rm${i.recursive ? ' -r' : ''}: ${parts.join(' · ')}`
}

files.hooks/parse.ts:
// Splits a Bash command into simple commands (around ; && || | & newlines) and finds what
// an `rm` would delete, without running anything. Best effort, like a human skimming the
// line: no aliases, functions, find -delete, bash -c, heredocs or scripts. Good enough to
// warn, never to authorize.

export type Target = {
  text: string
  // directory the rm runs in, relative to the session cwd (or absolute, or ~); undefined after a `cd` we can't follow
  dir: string | undefined
  glob: boolean
  // $VAR, $(..), `..`, xargs input: only the shell knows; never expanded here, expanding would run it
  dynamic: boolean
}

export type Removal = { recursive: boolean; targets: Target[] }

export type Word = { text: string; glob: boolean; dynamic: boolean; start: number; end: number }
export type Token = Word | { op: string }

// one simple command: its source text from the command name on, its words, the dir it runs in
export type Segment = { text: string; words: Word[]; dir: string | undefined }

const WRAPPERS = new Set(['sudo', 'command', 'builtin', 'nohup', 'time', 'nice', 'exec'])

export function lex(src: string): Token[] {
  const out: Token[] = []
  let word: Word | undefined
  let skipNext = false
  const push = (at: number) => {
    if (word) {
      word.end = at
      if (skipNext) skipNext = false
      else out.push(word)
    }
    word = undefined
  }

  for (let i = 0; i < src.length; i++) {
    const c = src[i]!
    const cur = () => (word ??= { text: '', glob: false, dynamic: false, start: i, end: i })
    if (c === ' ' || c === '\t') {
      push(i)
    } else if (c === '\n' || c === ';' || c === '(' || c === ')') {
      push(i)
      out.push({ op: ';' })
    } else if (c === '&' || c === '|') {
      push(i)
      if (src[i + 1] === c) i++
      out.push({ op: c })
    } else if (c === '>' || c === '<') {
      // redirection: drop a leading fd number and the redirect target, neither is an argument
      if (word && /^\d+$/.test(word.text)) word = undefined
      push(i)
      if (src[i + 1] === '>' || src[i + 1] === '&') i++
      if (src[i] === '&') {
        while (/[\d-]/.test(src[i + 1] ?? '')) i++
      } else {
        skipNext = true
      }
    } else if (c === '#' && !word) {
      while (i < src.length && src[i] !== '\n') i++
      i--
    } else if (c === "'") {
      const w = cur()
      const end = src.indexOf("'", i + 1)
      const stop = end < 0 ? src.length : end
      w.text += src.slice(i + 1, stop)
      i = stop
    } else if (c === '"') {
      const w = cur()
      for (i++; i < src.length && src[i] !== '"'; i++) {
        if (src[i] === '\\' && /["\\$`]/.test(src[i + 1] ?? '')) i++
        else if (src[i] === '$' || src[i] === '`') w.dynamic = true
        w.text += src[i]
      }
    } else if (c === '\\') {
      cur().text += src[++i] ?? ''
    } else if ((c === '$' && src[i + 1] === '(') || c === '`') {
      // command substitution stays one opaque word, however many words it holds
      const w = cur()
      w.dynamic = true
      let depth = 0
      const start = i
      for (; i < src.length; i++) {
        const d = src[i]!
        if (c === '`' ? d === '`' && i > start : d === ')' && --depth === 0) break
        if (c !== '`' && d === '(') depth++
      }
      w.text += src.slice(start, i + 1)
    } else {
      const w = cur()
      if (c === '$') w.dynamic = true
      if (c === '*' || c === '?' || c === '[') w.glob = true
      w.text += c
    }
  }
  push(src.length)
  return out
}

export const isWord = (t: Token): t is Word => 'text' in t

const basename = (w: Word) => w.text.split('/').pop()

function joinDir(dir: string | undefined, next: Word | undefined): string | undefined {
  if (!next) return '~'
  if (dir === undefined || next.dynamic || next.text === '-') return undefined
  const p = next.text
  if (p.startsWith('/') || p.startsWith('~')) return p
  return dir === '' ? p : `${dir}/${p}`
}

export function segments(command: string): Segment[] {
  const groups: Word[][] = [[]]
  for (const t of lex(command)) {
    if (isWord(t)) groups[groups.length - 1]!.push(t)
    else groups.push([])
  }

  let dir: string | undefined = ''
  const out: Segment[] = []
  for (const g of groups) {
    let i = 0
    while (i < g.length && (WRAPPERS.has(g[i]!.text) || /^[A-Za-z_]\w*=/.test(g[i]!.text) || (i > 0 && g[i]!.text.startsWith('-')))) i++
    const words = g.slice(i)
    if (!words.length) continue
    out.push({ text: command.slice(words[0]!.start, words[words.length - 1]!.end), words, dir })
    if (basename(words[0]!) === 'cd') dir = joinDir(dir, words[1])
  }
  return out
}

export function parse(command: string): Removal | undefined {
  if (!/\brm\b/.test(command)) return undefined

  let recursive = false
  const targets: Target[] = []
  for (const { words, dir } of segments(command)) {
    const [head, ...args] = words
    const name = basename(head!)
    if (name === 'xargs' && args.some(a => basename(a) === 'rm')) {
      // targets arrive on stdin from the left side of the pipe
      targets.push({ text: '<xargs>', dir, glob: false, dynamic: true })
    } else if (name === 'rm') {
      let flags = true
      for (const a of args) {
        if (flags && a.text === '--') flags = false
        else if (flags && a.text.startsWith('-') && a.text.length > 1 && !a.dynamic) {
          if (a.text === '--recursive' || (!a.text.startsWith('--') && /[rR]/.test(a.text))) recursive = true
        } else {
          targets.push({ text: a.text, dir, glob: a.glob, dynamic: a.dynamic })
        }
      }
    }
  }

  return targets.length ? { recursive, targets } : undefined
}

files.hooks/probe.ts:
// Measures what a Removal would take: files, size, and how much of it git can't bring back.
// Read-only probes through argv (never a shell: a target like $(curl ..) must not run).

import type { Removal } from './parse'

export type RunResult = { exitCode: number; stdout: string; stderr?: string; isStdoutTruncated: boolean }
export type Stat = { kind: 'file' | 'dir' | 'other'; size: number; isLink: boolean }

export type Host = {
  cwd: string
  home: string | undefined
  run: (argv: readonly string[], init: { cwd?: string; timeoutMs: number }) => Promise<RunResult>
  stat: (path: string) => Promise<Stat | undefined>
  list: (dir: string) => Promise<readonly { name: string }[]>
}

export type Flag = 'root' | 'home' | 'cwd' | 'git-dir' | 'outside-cwd'

export type Impact = {
  recursive: boolean
  paths: number
  missing: number
  unresolved: number
  dirsWithoutR: number
  files: number
  filesCapped: boolean
  bytes: number
  sizeUnknown: boolean
  // modified or untracked in git, or outside any repo: gone for good
  unsaved: number
  tracked: number
  ignored: number
  gitUnknown: boolean
  flags: Flag[]
  // per existing path, for the pane
  items: { path: string; kind: 'file' | 'dir'; files: number; bytes: number }[]
}

const PROBE_MS = 3000
const MAX_PATHS = 200

export function normalize(path: string): string {
  const parts: string[] = []
  for (const p of path.split('/')) {
    if (p === '' || p === '.') continue
    if (p === '..') parts.pop()
    else parts.push(p)
  }
  return `/${parts.join('/')}`
}

export function absolute(host: Host, dir: string, text: string): string | undefined {
  const base = text.startsWith('/') || text.startsWith('~') || !dir ? text : `${dir}/${text}`
  if (base.startsWith('/')) return normalize(base)
  if (base === '~' || base.startsWith('~/')) return host.home ? normalize(host.home + base.slice(1)) : undefined
  if (base.startsWith('~')) return undefined // ~user
  return normalize(`${host.cwd}/${base}`)
}

function globRegex(pattern: string): RegExp {
  let re = ''
  for (let i = 0; i < pattern.length; i++) {
    const c = pattern[i]!
    if (c === '*') re += '[^/]*'
    else if (c === '?') re += '[^/]'
    else if (c === '[') {
      const end = pattern.indexOf(']', i + 1)
      if (end < 0) re += '\\['
      else {
        re += `[${pattern.slice(i + 1, end).replace(/^!/, '^').replace(/\\/g, '\\\\')}]`
        i = end
      }
    } else re += c.replace(/[.+^${}()|\\]/g, '\\$&')
  }
  return new RegExp(`^${re}$`)
}

async function expand(host: Host, abs: string): Promise<string[] | undefined> {
  const cut = abs.lastIndexOf('/')
  const parent = abs.slice(0, cut) || '/'
  const pattern = abs.slice(cut + 1)
  if (/[*?[]/.test(parent)) return undefined
  const re = globRegex(pattern)
  const hidden = pattern.startsWith('.')
  const entries = await host.list(parent).catch(() => [])
  return entries
    .filter(e => re.test(e.name) && (hidden || !e.name.startsWith('.')))
    .map(e => normalize(`${parent}/${e.name}`))
}

const lines = (s: string) => s.split('\n').filter(Boolean).length

function flagsOf(host: Host, path: string): Flag[] {
  const within = (a: string, b: string) => b === a || b.startsWith(a === '/' ? '/' : `${a}/`)
  const flags: Flag[] = []
  if (path === '/') flags.push('root')
  else if (host.home && within(path, host.home)) flags.push('home')
  else if (within(path, host.cwd)) flags.push('cwd')
  if (path.split('/').includes('.git')) flags.push('git-dir')
  if (!within(host.cwd, path)) flags.push('outside-cwd')
  return flags
}

type GitCount = { repo: boolean; tracked: number; unsaved: number; untracked: number } | undefined

async function gitCount(host: Host, path: string, isDir: boolean): Promise<GitCount> {
  const at = isDir ? path : path.slice(0, path.lastIndexOf('/')) || '/'
  const opts = { cwd: at, timeoutMs: PROBE_MS }
  const top = await host.run(['git', 'rev-parse', '--show-toplevel'], opts)
  if (top.exitCode !== 0) return { repo: false, tracked: 0, unsaved: 0, untracked: 0 }
  const [ls, st] = await Promise.all([
    host.run(['git', 'ls-files', '-z', '--', path], opts),
    host.run(['git', 'status', '--porcelain', '-z', '--untracked-files=all', '--', path], opts),
  ])
  if (ls.exitCode !== 0 || st.exitCode !== 0) return undefined
  let unsaved = 0
  let untracked = 0
  const recs = st.stdout.split('\0').filter(Boolean)
  for (let i = 0; i < recs.length; i++) {
    const code = recs[i]!.slice(0, 2)
    if (code.startsWith('R') || code.startsWith('C')) i++ // rename/copy carry the old path as an extra record
    if (code === '??') untracked++
    if (code[1] !== ' ' || code === '??') unsaved++ // worktree side differs: rm loses it
  }
  return { repo: true, tracked: ls.stdout.split('\0').filter(Boolean).length, unsaved, untracked }
}

export async function probe(host: Host, removal: Removal): Promise<Impact> {
  const impact: Impact = {
    recursive: removal.recursive,
    paths: 0,
    missing: 0,
    unresolved: 0,
    dirsWithoutR: 0,
    files: 0,
    filesCapped: false,
    bytes: 0,
    sizeUnknown: false,
    unsaved: 0,
    tracked: 0,
    ignored: 0,
    gitUnknown: false,
    flags: [],
    items: [],
  }

  const paths = new Set<string>()
  for (const t of removal.targets) {
    const abs = t.dynamic || t.dir === undefined ? undefined : absolute(host, t.dir, t.text)
    if (!abs) {
      impact.unresolved++
      continue
    }
    if (!t.glob) {
      paths.add(abs)
      continue
    }
    const hits = await expand(host, abs)
    if (!hits) impact.unresolved++
    else if (!hits.length) impact.missing++
    else hits.forEach(p => paths.add(p))
  }

  const flags = new Set<Flag>()
  await Promise.all(
    [...paths].slice(0, MAX_PATHS).map(async path => {
      const st = await host.stat(path).catch(() => undefined)
      if (!st) return void impact.missing++
      impact.paths++
      const isDir = st.kind === 'dir' && !st.isLink
      if (isDir && !removal.recursive) return void impact.dirsWithoutR++
      flagsOf(host, path).forEach(f => flags.add(f))

      let files = 1
      let bytes = st.size
      if (isDir) {
        const [du, find] = await Promise.allSettled([
          host.run(['du', '-sk', path], { timeoutMs: PROBE_MS }),
          host.run(['find', path, '-type', 'f'], { timeoutMs: PROBE_MS }),
        ])
        bytes = du.status === 'fulfilled' && du.value.stdout ? parseInt(du.value.stdout, 10) * 1024 : 0
        if (!bytes && du.status !== 'fulfilled') impact.sizeUnknown = true
        if (find.status === 'fulfilled') {
          files = lines(find.value.stdout)
          if (find.value.isStdoutTruncated) impact.filesCapped = true
        } else {
          files = 0
          impact.filesCapped = true
        }
      }
      impact.bytes += bytes
      impact.files += files
      impact.items.push({ path, kind: isDir ? 'dir' : 'file', files, bytes })

      const git = await gitCount(host, path, isDir).catch(() => undefined)
      if (!git) return void (impact.gitUnknown = true)
      if (!git.repo) return void (impact.unsaved += files)
      impact.tracked += git.tracked
      impact.unsaved += git.unsaved
      impact.ignored += Math.max(0, files - git.tracked - git.untracked)
    }),
  )
  if (paths.size > MAX_PATHS) impact.unresolved += paths.size - MAX_PATHS
  impact.flags = [...flags]
  return impact
}

files.hooks/rules.ts:
// User rules: a regex over one simple command, and a read-only preview command to run when
// it matches. "kdel.match": "^kubectl delete (.+)$", "kdel.preview": "kubectl delete $1 --dry-run=server -o name".
//
// The preview runs WITHOUT asking, so it is held to: argv only (never a shell), no ; | &
// after filling in, no $VAR or $(..) left (a capture like $(curl ..) must not run), and
// no shell or wrapper as the program. Whether the preview itself is read-only is the
// rule author's job.

import { isWord, lex, type Segment, type Word } from './parse'

export type Rule = { id: string; match: RegExp; preview: string }

export type Plan =
  | { rule: string; segment: string; argv: string[]; dir: string }
  | { rule: string; segment: string; skip: string }

type Options = Readonly<Record<string, unknown>>

export const SOURCES = ['user', 'project', 'local', 'flag', 'policy'] as const

// a program that would run its arguments as code, or hide what runs
const REFUSED = new Set(['sh', 'bash', 'zsh', 'fish', 'dash', 'ksh', 'eval', 'exec', 'env', 'sudo', 'xargs', 'nohup', 'command', 'builtin', 'time', 'nice', 'python', 'python3', 'node', 'perl', 'ruby'])

// register's `options` only carries keys plugin.json's userConfig declares, so dotted keys
// never arrive there: read pluginConfigs per source, the last source setting a key wins.
export function optionsOf(sources: readonly unknown[]): Options {
  const out: Record<string, unknown> = {}
  for (const s of sources) {
    const configs = (s as { pluginConfigs?: Record<string, { options?: unknown }> } | undefined)?.pluginConfigs ?? {}
    for (const [key, v] of Object.entries(configs)) {
      if (key !== 'blast-radius' && !key.startsWith('blast-radius@')) continue
      const opts = v?.options
      if (opts && typeof opts === 'object' && !Array.isArray(opts)) Object.assign(out, opts)
    }
  }
  return out
}

export function rulesOf(options: Options): { rules: Rule[]; errors: string[] } {
  const ids = options.rules
  const rules: Rule[] = []
  const errors: string[] = []
  for (const id of Array.isArray(ids) ? ids.map(String) : []) {
    const match = options[`${id}.match`]
    const preview = options[`${id}.preview`]
    if (typeof match !== 'string' || typeof preview !== 'string') {
      errors.push(`${id}: needs "${id}.match" and "${id}.preview" strings`)
      continue
    }
    try {
      rules.push({ id, match: new RegExp(match), preview })
    } catch (err) {
      errors.push(`${id}: bad regex: ${String(err)}`)
    }
  }
  return { rules, errors }
}

export function plan(rule: Rule, seg: Segment): Plan | undefined {
  const m = rule.match.exec(seg.text)
  if (!m) return undefined
  const base = { rule: rule.id, segment: seg.text }
  if (seg.dir === undefined) return { ...base, skip: 'runs after a cd we cannot follow' }

  const filled = rule.preview.replace(/\$(\d)/g, (_, n: string) => m[Number(n)] ?? '')
  const tokens = lex(filled)
  if (!tokens.every(isWord)) return { ...base, skip: 'preview would chain commands (; | &)' }
  const words = tokens as Word[]
  if (!words.length) return { ...base, skip: 'preview is empty' }
  if (words.some(w => w.dynamic)) return { ...base, skip: 'preview holds $VAR or $(..)' }
  const program = words[0]!.text.split('/').pop()!
  if (REFUSED.has(program)) return { ...base, skip: `${program} is not allowed as a preview` }
  return { ...base, argv: words.map(w => w.text), dir: seg.dir }
}

